      const X = { sc: c.scB, adj: c.adjB, rep: report(ctx, 'baseline', raw, '89e79f49'), n: rawCount(raw),
        map: ctx.json(`${RR}/baseline-pre-barrel/blind-rule-mapping.json`).mapping,
        scripts: ['ue-baseline-live.ts', 'ue-graph.ts', 'ue-score.ts'].filter((f) => ctx.exists(`scripts/v1.3/${f}`)).length };
      return results(BASE, X);
